/**
 * BibTeX Parser for React Portfolio
 * Parses .bib files and converts them to publication objects
 */

// Parse a single BibTeX entry
const parseBibEntry = (entry) => {
  const result = {};
  
  // Extract entry type and key
  const typeMatch = entry.match(/@(\w+)\s*\{\s*([^,]*)/);
  if (typeMatch) {
    result.entryType = typeMatch[1].toLowerCase();
    result.citationKey = typeMatch[2].trim();
  }
  
  // Extract fields
  const fieldRegex = /(\w+)\s*=\s*\{([^}]*(?:\{[^}]*\}[^}]*)*)\}/g;
  let match;
  
  while ((match = fieldRegex.exec(entry)) !== null) {
    const fieldName = match[1].toLowerCase();
    let fieldValue = match[2].trim();
    
    // Clean up LaTeX formatting
    fieldValue = cleanLatex(fieldValue);
    
    result[fieldName] = fieldValue;
  }
  
  return result;
};

// Clean LaTeX special characters and formatting
const cleanLatex = (text) => {
  if (!text) return '';
  
  return text
    // Remove LaTeX commands
    .replace(/\\textbf\{([^}]*)\}/g, '$1')
    .replace(/\\textit\{([^}]*)\}/g, '$1')
    .replace(/\\emph\{([^}]*)\}/g, '$1')
    .replace(/\\\&/g, '&')
    .replace(/\\%/g, '%')
    .replace(/\\_/g, '_')
    .replace(/\\#/g, '#')
    .replace(/\\\$/g, '$')
    // Handle special characters
    .replace(/\{\\"\{([aeiouAEIOU])\}\}/g, '$1') // umlauts
    .replace(/\\"\{([aeiouAEIOU])\}/g, '$1')
    .replace(/\\"([aeiouAEIOU])/g, '$1')
    .replace(/\{\\'([aeiouAEIOU])\}/g, '$1') // accents
    .replace(/\\'([aeiouAEIOU])/g, '$1')
    .replace(/\\`([aeiouAEIOU])/g, '$1')
    .replace(/\\~([nN])/g, '$1')
    .replace(/\\c\{([cC])\}/g, '$1')
    // Remove remaining braces
    .replace(/\{([^}]*)\}/g, '$1')
    // Clean up whitespace
    .replace(/\s+/g, ' ')
    .trim();
};

// Parse author string into array
const parseAuthors = (authorString) => {
  if (!authorString) return [];
  
  // Split by " and " (BibTeX standard)
  const authors = authorString.split(/\s+and\s+/i);
  
  return authors.map(author => {
    author = author.trim();
    
    // Handle "Last, First" format
    if (author.includes(',')) {
      const [last, first] = author.split(',').map(s => s.trim());
      return `${first} ${last}`;
    }
    
    return author;
  });
};

// Determine publication type
const getPublicationType = (entry) => {
  const entryType = entry.entryType?.toLowerCase();
  const venue = (entry.journal || entry.booktitle || '').toLowerCase();
  
  if (entryType === 'article' && entry.journal) {
    if (venue.includes('arxiv') || entry.eprint) {
      return 'preprint';
    }
    return 'journal';
  }
  
  if (entryType === 'inproceedings' || entryType === 'conference') {
    return 'conference';
  }
  
  if (entryType === 'phdthesis' || entryType === 'mastersthesis') {
    return 'thesis';
  }
  
  if (entryType === 'book' || entryType === 'inbook') {
    return 'book';
  }
  
  if (entry.eprint || venue.includes('arxiv')) {
    return 'preprint';
  }
  
  return 'other';
};

// Build links object from entry
const buildLinks = (entry) => {
  const links = {};
  
  // URL or DOI
  if (entry.url) {
    links.paper = entry.url;
  } else if (entry.doi) {
    links.paper = `https://doi.org/${entry.doi}`;
    links.doi = entry.doi;
  }
  
  // arXiv
  if (entry.eprint) {
    links.arxiv = entry.eprint;
    if (!links.paper) {
      links.paper = `https://arxiv.org/abs/${entry.eprint}`;
    }
  }
  
  // PDF
  if (entry.pdf) {
    links.pdf = entry.pdf;
  }
  
  // Code/GitHub
  if (entry.code || entry.github) {
    links.code = entry.code || entry.github;
  }
  
  return links;
};

// Get venue name
const getVenue = (entry) => {
  if (entry.journal) return entry.journal;
  if (entry.booktitle) return entry.booktitle;
  if (entry.publisher) return entry.publisher;
  if (entry.school) return entry.school;
  if (entry.institution) return entry.institution;
  if (entry.eprint) return 'arXiv preprint';
  return '';
};

// Main parser function
export const parseBibTeX = (bibContent) => {
  if (!bibContent) return [];
  
  // Split into individual entries
  const entries = [];
  const entryRegex = /@\w+\s*\{[^@]*\}/g;
  let match;
  
  while ((match = entryRegex.exec(bibContent)) !== null) {
    entries.push(match[0]);
  }
  
  // Parse each entry
  const publications = entries.map(entry => {
    const parsed = parseBibEntry(entry);
    
    return {
      title: parsed.title || 'Untitled',
      authors: parseAuthors(parsed.author),
      venue: getVenue(parsed),
      year: parsed.year || new Date().getFullYear().toString(),
      type: getPublicationType(parsed),
      links: buildLinks(parsed),
      abstract: parsed.abstract || '',
      keywords: parsed.keywords ? parsed.keywords.split(',').map(k => k.trim()) : [],
      citationKey: parsed.citationKey,
    };
  });
  
  // Sort by year (newest first)
  return publications.sort((a, b) => parseInt(b.year) - parseInt(a.year));
};

// Fetch and parse a .bib file
export const fetchAndParseBib = async (bibPath) => {
  try {
    const response = await fetch(bibPath);
    if (!response.ok) {
      throw new Error(`Failed to fetch ${bibPath}`);
    }
    const bibContent = await response.text();
    return parseBibTeX(bibContent);
  } catch (error) {
    console.error('Error loading BibTeX file:', error);
    return [];
  }
};

export default parseBibTeX;
