import React, { useState } from 'react';
import { Box, Typography, Container, Grid, Link, Dialog, IconButton, useTheme } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';

const postcardRotations = [-2.5, 1.8, -1.2, 2.1, -1.8, 1.4, -2.2, 1.6];

const PersonRow = ({ person, type }) => (
  <Box
    sx={{
      py: 0.6,
      borderBottom: '1px solid',
      borderColor: 'divider',
      transition: 'all 0.2s ease',
      '&:hover': {
        borderColor: type === 'mentor' ? 'secondary.main' : 'primary.main',
        pl: 0.75,
      },
    }}
  >
    <Typography sx={{ fontSize: '0.88rem', color: 'text.primary', lineHeight: 1.4 }}>
      {person.link ? (
        <Link
          href={person.link}
          target="_blank"
          rel="noopener noreferrer"
          underline="hover"
          sx={{ color: 'text.primary', '&:hover': { color: 'secondary.main' } }}
        >
          {person.name}
        </Link>
      ) : (
        person.name
      )}
    </Typography>
    <Typography variant="caption" sx={{ color: 'text.secondary', fontSize: '0.75rem' }}>
      {person.role}
    </Typography>
  </Box>
);

const Mentorship = ({ mentors, mentees, gallery }) => {
  const theme = useTheme();
  const [selectedImage, setSelectedImage] = useState(null);
  const [hovered, setHovered] = useState(null);

  if ((!mentors || mentors.length === 0) && (!mentees || mentees.length === 0)) return null;

  return (
    <Box id="mentorship" sx={{ py: { xs: 4, md: 5 }, backgroundColor: 'background.default' }}>
      <Container maxWidth="lg">
        <Box sx={{ borderBottom: '2px solid', borderColor: 'secondary.main', pb: 2, mb: 3 }}>
          <Typography
            variant="h4"
            sx={{
              fontWeight: 500,
              color: 'secondary.main',
              fontSize: '1.1rem',
              fontFamily: '"Courier New", monospace',
              letterSpacing: '0.05em',
            }}
          >
            &gt;&gt; people
          </Typography>
        </Box>

        {/* Mentors + Mentees */}
        <Grid container spacing={4} sx={{ mb: gallery && gallery.length ? 4 : 0 }}>
          {mentors && mentors.length > 0 && (
            <Grid item xs={12} md={6}>
              <Typography
                variant="caption"
                sx={{
                  color: 'text.secondary',
                  fontSize: '0.75rem',
                  fontFamily: '"Courier New", monospace',
                  textTransform: 'uppercase',
                  letterSpacing: '0.06em',
                  display: 'block',
                  mb: 1,
                }}
              >
                Mentors
              </Typography>
              {mentors.map((mentor, i) => (
                <PersonRow key={i} person={mentor} type="mentor" />
              ))}
            </Grid>
          )}

          {mentees && mentees.length > 0 && (
            <Grid item xs={12} md={6}>
              <Typography
                variant="caption"
                sx={{
                  color: 'text.secondary',
                  fontSize: '0.75rem',
                  fontFamily: '"Courier New", monospace',
                  textTransform: 'uppercase',
                  letterSpacing: '0.06em',
                  display: 'block',
                  mb: 1,
                }}
              >
                Students Mentored
              </Typography>
              {mentees.map((mentee, i) => (
                <PersonRow key={i} person={mentee} type="mentee" />
              ))}
            </Grid>
          )}
        </Grid>

        {/* Gallery postcards — no heading */}
        {gallery && gallery.length > 0 && (
          <>
            <Box
              sx={{
                display: 'flex',
                flexWrap: 'wrap',
                gap: { xs: 2.5, md: 3.5 },
                justifyContent: 'flex-start',
                py: 2,
              }}
            >
              {gallery.map((item, index) => {
                const rotation = postcardRotations[index % postcardRotations.length];
                const isHovered = hovered === index;
                return (
                  <Box
                    key={index}
                    onClick={() => setSelectedImage(item)}
                    onMouseEnter={() => setHovered(index)}
                    onMouseLeave={() => setHovered(null)}
                    sx={{
                      width: { xs: 130, sm: 155, md: 175 },
                      cursor: 'pointer',
                      transform: isHovered ? 'rotate(0deg) scale(1.06)' : `rotate(${rotation}deg)`,
                      transition: 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s ease',
                      boxShadow: isHovered ? '0 14px 30px rgba(0,0,0,0.25)' : '0 3px 10px rgba(0,0,0,0.15)',
                      zIndex: isHovered ? 10 : 1,
                      position: 'relative',
                      flexShrink: 0,
                    }}
                  >
                    <Box
                      sx={{
                        backgroundColor: theme.palette.mode === 'light' ? '#fafaf8' : '#e8e4de',
                        p: '7px 7px 26px 7px',
                        borderRadius: '1px',
                      }}
                    >
                      <Box
                        component="img"
                        src={item.image}
                        alt={item.caption}
                        loading="lazy"
                        sx={{ width: '100%', aspectRatio: '4/3', objectFit: 'cover', display: 'block' }}
                      />
                      {item.caption && (
                        <Typography
                          sx={{
                            mt: 0.75,
                            fontSize: '0.62rem',
                            color: '#666',
                            fontFamily: '"Courier New", monospace',
                            textAlign: 'center',
                            lineHeight: 1.3,
                            px: 0.5,
                          }}
                        >
                          {item.caption}
                        </Typography>
                      )}
                    </Box>
                  </Box>
                );
              })}
            </Box>

            {/* Lightbox */}
            <Dialog
              open={!!selectedImage}
              onClose={() => setSelectedImage(null)}
              maxWidth="lg"
              PaperProps={{
                sx: { backgroundColor: 'transparent', boxShadow: 'none', overflow: 'visible' },
              }}
            >
              <IconButton
                onClick={() => setSelectedImage(null)}
                sx={{
                  position: 'absolute',
                  top: -40,
                  right: 0,
                  color: '#fff',
                  backgroundColor: 'rgba(0,0,0,0.5)',
                  '&:hover': { backgroundColor: 'rgba(0,0,0,0.7)' },
                }}
              >
                <CloseIcon />
              </IconButton>
              {selectedImage && (
                <Box sx={{ textAlign: 'center' }}>
                  <img
                    src={selectedImage.image}
                    alt={selectedImage.caption}
                    style={{ maxWidth: '90vw', maxHeight: '80vh', borderRadius: 4 }}
                  />
                  {selectedImage.caption && (
                    <Typography
                      variant="body1"
                      sx={{ color: '#fff', mt: 2, textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}
                    >
                      {selectedImage.caption}
                    </Typography>
                  )}
                </Box>
              )}
            </Dialog>
          </>
        )}
      </Container>
    </Box>
  );
};

export default Mentorship;
