import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Container,
  Chip,
  IconButton,
  Collapse,
  Link,
  useTheme,
  CircularProgress,
} from '@mui/material';
import ArticleIcon from '@mui/icons-material/Article';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import PictureAsPdfIcon from '@mui/icons-material/PictureAsPdf';
import { fetchAndParseBib } from '../utils/bibParser';

// ============ CONFIGURATION ============
// Set your .bib file path here (relative to public folder)
const BIB_FILE_PATH = process.env.PUBLIC_URL + '/publications.bib';

// Your name variations for highlighting
const MY_NAMES = [
  'Sutapa Dey Tithi',
  'S. D. Tithi',
  'Tithi, Sutapa',
  'SD Tithi',
  'Sutapa Tithi',
  'Tithi, S',
  'S Tithi',
];
// ========================================

const Publications = ({ research: fallbackResearch }) => {
  const theme = useTheme();
  const [expandedId, setExpandedId] = useState(null);
  const [publications, setPublications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [usingBib, setUsingBib] = useState(false);

  useEffect(() => {
    const loadPublications = async () => {
      setLoading(true);
      try {
        // Try to load from .bib file first
        const bibPubs = await fetchAndParseBib(BIB_FILE_PATH);
        if (bibPubs && bibPubs.length > 0) {
          setPublications(bibPubs);
          setUsingBib(true);
        } else {
          // Fall back to data.js if no bib file or empty
          setPublications(fallbackResearch || []);
          setUsingBib(false);
        }
      } catch (error) {
        console.warn('BibTeX file not found, using fallback data:', error.message);
        setPublications(fallbackResearch || []);
        setUsingBib(false);
      }
      setLoading(false);
    };

    loadPublications();
  }, [fallbackResearch]);

  // Group publications by year
  const groupedByYear = publications.reduce((acc, pub) => {
    const year = pub.year || 'Unknown';
    if (!acc[year]) acc[year] = [];
    acc[year].push(pub);
    return acc;
  }, {});

  const years = Object.keys(groupedByYear).sort((a, b) => b - a);

  const toggleExpand = (id) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const getTypeColor = (type) => {
    switch (type) {
      case 'preprint':
        return theme.palette.mode === 'dark' ? '#ffd54f' : '#f9a825';
      case 'journal':
        return theme.palette.mode === 'dark' ? '#81c784' : '#388e3c';
      case 'thesis':
        return theme.palette.mode === 'dark' ? '#64b5f6' : '#1976d2';
      case 'conference':
      default:
        return theme.palette.primary.main;
    }
  };

  const getTypeLabel = (type) => {
    const labels = {
      preprint: 'Preprint',
      journal: 'Journal',
      conference: 'Conference',
      thesis: 'Thesis',
      book: 'Book',
    };
    return labels[type] || type;
  };

  // Check if author name matches your name
  const isMyName = (name) => {
    return MY_NAMES.some((n) => name.toLowerCase().includes(n.toLowerCase()));
  };

  if (loading) {
    return (
      <Box
        id="publications"
        sx={{
          py: 8,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: 300,
          backgroundColor: 'background.default',
        }}
      >
        <CircularProgress color="primary" />
      </Box>
    );
  }

  return (
    <Box
      id="publications"
      sx={{
        py: { xs: 4, md: 5 },
        backgroundColor: 'background.default',
      }}
    >
      <Container maxWidth="lg">
        {/* Section Header */}
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            mb: 4,
            pb: 2,
            borderBottom: '2px solid',
            borderColor: 'secondary.main',
          }}
        >
          <Typography
            variant="h4"
            sx={{
              fontWeight: 500,
              color: 'secondary.main',
              fontSize: '1.1rem',
              fontFamily: '"Courier New", monospace',
              letterSpacing: '0.05em',
            }}
          >
            &gt;&gt; publications
          </Typography>
        </Box>

        {/* Source indicator */}
        {usingBib && (
          <Typography
            variant="caption"
            sx={{
              display: 'block',
              color: 'text.secondary',
              mb: 3,
              fontStyle: 'italic',
            }}
          >
            {/* 📚 Loaded from publications.bib ({publications.length} entries) */}
          </Typography>
        )}

        {/* No publications message */}
        {publications.length === 0 && (
          <Typography variant="body1" sx={{ color: 'text.secondary', textAlign: 'center', py: 4 }}>
            No publications found. Add a publications.bib file to your public folder.
          </Typography>
        )}

        {/* Publications by Year */}
        {years.map((year) => (
          <Box key={year} sx={{ mb: 2.5 }}>
            <Typography
              variant="caption"
              sx={{
                color: 'text.secondary',
                fontWeight: 700,
                mb: 1.5,
                pb: 0.5,
                borderBottom: '1px solid',
                borderColor: 'divider',
                display: 'inline-block',
                fontSize: '0.8rem',
                fontFamily: '"Courier New", monospace',
                letterSpacing: '0.05em',
              }}
            >
              {year}
            </Typography>

            {groupedByYear[year].map((pub, idx) => {
              const pubId = `${year}-${idx}`;
              const isExpanded = expandedId === pubId;

              return (
                <Box
                  key={pubId}
                  sx={{
                    py: 1.5,
                    borderBottom: '1px solid',
                    borderColor: 'divider',
                    '&:last-child': {
                      borderBottom: 'none',
                    },
                  }}
                >
                  {/* Title */}
                  <Typography
                    variant="body2"
                    sx={{
                      fontWeight: 500,
                      color: 'text.primary',
                      lineHeight: 1.4,
                      mb: 0.4,
                      fontSize: '0.9rem',
                    }}
                  >
                    {pub.title}
                  </Typography>

                  {/* Authors */}
                  <Typography
                    variant="caption"
                    sx={{
                      color: 'text.secondary',
                      mb: 0.3,
                      fontSize: '0.8rem',
                      display: 'block',
                    }}
                  >
                    {pub.authors?.map((author, i) => (
                      <span key={i}>
                        {isMyName(author) ? (
                          <Box
                            component="span"
                            sx={{ fontWeight: 600, color: 'text.primary' }}
                          >
                            {author}
                          </Box>
                        ) : (
                          author
                        )}
                        {i < pub.authors.length - 1 && ', '}
                      </span>
                    ))}
                  </Typography>

                  {/* Venue */}
                  <Typography
                    variant="caption"
                    sx={{
                      color: 'text.secondary',
                      fontStyle: 'italic',
                      mb: 0.6,
                      fontSize: '0.8rem',
                      display: 'block',
                    }}
                  >
                    {pub.venue}
                    {pub.venue && pub.year && ', '}
                    {pub.year}
                  </Typography>

                  {/* Links and Type Badge */}
                  <Box
                    sx={{
                      display: 'flex',
                      gap: 1,
                      flexWrap: 'wrap',
                      alignItems: 'center',
                    }}
                  >
                    {/* Type Badge */}
                    {pub.type && (
                      <Typography
                        variant="caption"
                        sx={{
                          color: 'text.secondary',
                          border: '1px solid',
                          borderColor: 'divider',
                          px: 0.6,
                          py: 0.2,
                          fontSize: '0.7rem',
                          fontFamily: '"Courier New", monospace',
                        }}
                      >
                        {getTypeLabel(pub.type)}
                      </Typography>
                    )}

                    {/* Paper Link */}
                    {pub.links?.paper && (
                      <Link
                        href={pub.links.paper}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 0.3,
                          fontSize: '0.75rem',
                          color: 'text.secondary',
                          textDecoration: 'underline',
                          fontFamily: '"Courier New", monospace',
                          '&:hover': {
                            color: 'text.primary',
                          },
                        }}
                      >
                        paper
                      </Link>
                    )}

                    {/* PDF Link */}
                    {pub.links?.pdf && (
                      <Link
                        href={pub.links.pdf}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 0.3,
                          fontSize: '0.75rem',
                          color: 'text.secondary',
                          textDecoration: 'underline',
                          fontFamily: '"Courier New", monospace',
                          '&:hover': {
                            color: 'text.primary',
                          },
                        }}
                      >
                        pdf
                      </Link>
                    )}

                    {/* DOI */}
                    {pub.links?.doi && (
                      <Link
                        href={`https://doi.org/${pub.links.doi}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 0.3,
                          fontSize: '0.75rem',
                          color: 'text.secondary',
                          textDecoration: 'underline',
                          fontFamily: '"Courier New", monospace',
                          '&:hover': {
                            color: 'text.primary',
                          },
                        }}
                      >
                        doi
                      </Link>
                    )}

                    {/* arXiv */}
                    {pub.links?.arxiv && (
                      <Link
                        href={`https://arxiv.org/abs/${pub.links.arxiv}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 0.3,
                          fontSize: '0.75rem',
                          color: 'text.secondary',
                          textDecoration: 'underline',
                          fontFamily: '"Courier New", monospace',
                          '&:hover': {
                            color: 'text.primary',
                          },
                        }}
                      >
                        arxiv
                      </Link>
                    )}

                      {/* Abstract Toggle */}
                      {pub.abstract && (
                        <IconButton
                          size="small"
                          onClick={() => toggleExpand(pubId)}
                          sx={{
                            ml: 'auto',
                            color: 'text.secondary',
                            '&:hover': {
                              color: 'primary.main',
                            },
                          }}
                          aria-label={isExpanded ? 'Hide abstract' : 'Show abstract'}
                        >
                          {isExpanded ? (
                            <ExpandLessIcon fontSize="small" />
                          ) : (
                            <ExpandMoreIcon fontSize="small" />
                          )}
                        </IconButton>
                      )}
                    </Box>

                    {/* Abstract (Collapsible) */}
                    <Collapse in={isExpanded}>
                      <Box
                        sx={{
                          mt: 0.8,
                          p: 1,
                          backgroundColor: 'background.alternate',
                          borderRadius: 0,
                          borderLeft: '1px solid',
                          borderColor: 'primary.main',
                        }}
                      >
                        <Typography
                          variant="caption"
                          sx={{
                            color: 'text.secondary',
                            lineHeight: 1.5,
                            fontSize: '0.7rem',
                            display: 'block',
                          }}
                        >
                          <strong>Abstract:</strong> {pub.abstract}
                        </Typography>
                      </Box>
                    </Collapse>
                </Box>
              );
            })}
          </Box>
        ))}
      </Container>
    </Box>
  );
};

export default Publications;