import React from 'react';
import { Box, Typography, Container, Link } from '@mui/material';

const ReadingList = ({ readingList }) => {
  if (!readingList || readingList.length === 0) return null;

  return (
    <Box id="reading" sx={{ py: { xs: 4, md: 5 }, backgroundColor: 'background.default' }}>
      <Container maxWidth="lg">
        <Box sx={{ borderBottom: '2px solid', borderColor: 'secondary.main', pb: 2, mb: 3 }}>
          <Typography
            variant="h4"
            sx={{
              fontWeight: 500,
              color: 'secondary.main',
              fontSize: '1.1rem',
              fontFamily: '"Courier New", monospace',
              letterSpacing: '0.05em',
            }}
          >
            &gt;&gt; links
          </Typography>
        </Box>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
          {readingList.map((item, i) => (
            <Typography
              key={i}
              sx={{
                fontFamily: '"Merriweather", Georgia, serif',
                fontSize: '0.88rem',
                color: 'text.secondary',
                lineHeight: 1.6,
              }}
            >
              <Link
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                sx={{
                  color: 'text.primary',
                  fontFamily: 'inherit',
                  fontSize: 'inherit',
                  textDecorationColor: 'currentColor',
                  '&:hover': { color: 'secondary.main' },
                }}
              >
                {item.label}
              </Link>
              {item.date && <>   {item.date}</>}
            </Typography>
          ))}
        </Box>
      </Container>
    </Box>
  );
};

export default ReadingList;
